import assert from 'node:assert/strict';
import {inflateRawSync} from 'node:zlib';

// Structural readers. These assert what the generated bytes ARE. They cannot
// and do not assert that Microsoft Excel, Adobe Acrobat or Microsoft Word open
// or render the file: no such application runs in this repository.
export function unzip(buffer){
 const end=(()=>{for(let i=buffer.length-22;i>=0;i--)if(buffer.readUInt32LE(i)===0x06054b50)return i;throw new Error('No end of central directory');})();
 const count=buffer.readUInt16LE(end+10),size=buffer.readUInt32LE(end+12),start=buffer.readUInt32LE(end+16);
 assert.equal(buffer.readUInt16LE(end+8),count);
 const files=new Map();let position=start;
 for(let i=0;i<count;i++){
  assert.equal(buffer.readUInt32LE(position),0x02014b50,'central directory signature');
  const method=buffer.readUInt16LE(position+10),crc=buffer.readUInt32LE(position+16),compressed=buffer.readUInt32LE(position+20),raw=buffer.readUInt32LE(position+24);
  const nameLength=buffer.readUInt16LE(position+28),extra=buffer.readUInt16LE(position+30),comment=buffer.readUInt16LE(position+32),offset=buffer.readUInt32LE(position+42);
  const name=buffer.subarray(position+46,position+46+nameLength).toString('utf8');
  assert.equal(buffer.readUInt32LE(offset),0x04034b50,'local header signature for '+name);
  assert.equal(buffer.subarray(offset+30,offset+30+buffer.readUInt16LE(offset+26)).toString('utf8'),name);
  assert.equal(buffer.readUInt32LE(offset+14),crc,'local and central CRC agree for '+name);
  const dataStart=offset+30+buffer.readUInt16LE(offset+26)+buffer.readUInt16LE(offset+28);
  const stored=buffer.subarray(dataStart,dataStart+compressed);
  const data=method===8?inflateRawSync(stored):Buffer.from(stored);
  assert.equal(data.length,raw,'declared uncompressed size for '+name);
  assert.equal(crc32(data),crc,'CRC32 of the stored member '+name);
  files.set(name,data);
  position+=46+nameLength+extra+comment;
 }
 assert.equal(position-start,size,'declared central directory size');
 return files;
}
const TABLE=(()=>{const t=new Int32Array(256);for(let i=0;i<256;i++){let c=i;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[i]=c;}return t;})();
function crc32(buffer){let c=-1;for(const byte of buffer)c=TABLE[(c^byte)&0xff]^(c>>>8);return (c^-1)>>>0;}

// A deliberately literal SpreadsheetML reader: it keeps each cell's declared
// type and style so a test can prove a number is a number, not a string.
export function sheetCells(xml){
 const rows=[];
 for(const [,attributes,body] of xml.matchAll(/<row ([^>]*)>([\s\S]*?)<\/row>/g)){
  const cells=[];
  for(const [,cellAttributes,cellBody] of body.matchAll(/<c ([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g)){
   const reference=/r="([A-Z]+\d+)"/.exec(cellAttributes)[1],style=/ s="(\d+)"/.exec(cellAttributes)?.[1]??null,type=/ t="([a-zA-Z]+)"/.exec(cellAttributes)?.[1]??'n';
   const inline=/<is><t[^>]*>([\s\S]*?)<\/t><\/is>/.exec(cellBody||''),value=/<v>([\s\S]*?)<\/v>/.exec(cellBody||'');
   cells.push({reference,style,type,raw:inline?inline[1]:value?value[1]:null,formula:/<f[ >]/.test(cellBody||'')});
  }
  rows.push({r:/r="(\d+)"/.exec(attributes)[1],cells});
 }
 return rows;
}
export const unescapeXml=value=>value.replace(/_x([0-9A-F]{4})_/g,(m,hex)=>String.fromCharCode(parseInt(hex,16))).replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');

// Enough of a PDF parser to prove the document is structurally valid: header,
// object table, cross-reference offsets, trailer and reachable page content.
export function readPdf(buffer){
 const text=buffer.toString('latin1');
 assert.match(text.slice(0,8),/^%PDF-1\.\d$/,'PDF header');
 assert.ok(text.trimEnd().endsWith('%%EOF'),'PDF trailer marker');
 const startxref=Number(/startxref\s+(\d+)\s+%%EOF\s*$/.exec(text)[1]);
 assert.equal(text.slice(startxref,startxref+4),'xref','startxref points at the cross-reference table');
 const table=/xref\n0 (\d+)\n([\s\S]*?)trailer/.exec(text.slice(startxref));
 const size=Number(table[1]),entries=table[2].match(/.{20}/gs);
 assert.equal(entries.length,size,'cross-reference entry count matches /Size');
 assert.match(entries[0],/^0000000000 65535 f \n$/s,'free head entry');
 const offsets=[];
 for(let i=1;i<size;i++){
  const entry=/^(\d{10}) (\d{5}) n \n$/s.exec(entries[i]);
  assert.ok(entry,'object '+i+' has a well formed in-use entry');
  const offset=Number(entry[1]);
  assert.equal(text.slice(offset,offset+String(i).length+7),i+' 0 obj\n','object '+i+' begins at its declared offset');
  offsets.push(offset);
 }
 const trailer=/trailer\n<<([\s\S]*?)>>/.exec(text.slice(startxref))[1];
 assert.equal(Number(/\/Size (\d+)/.exec(trailer)[1]),size);
 const root=Number(/\/Root (\d+) 0 R/.exec(trailer)[1]);
 const object=n=>text.slice(offsets[n-1]).match(/^\d+ 0 obj\n([\s\S]*?)\nendobj/)[1];
 assert.match(object(root),/\/Type\s*\/Catalog/,'root object is a catalog');
 const pagesRef=Number(/\/Pages (\d+) 0 R/.exec(object(root))[1]),pages=object(pagesRef);
 assert.match(pages,/\/Type\s*\/Pages/);
 const kids=[...pages.matchAll(/(\d+) 0 R/g)].map(m=>Number(m[1]));
 assert.equal(kids.length,Number(/\/Count (\d+)/.exec(pages)[1]),'/Count matches the kid array');
 let content='';
 for(const kid of kids){
  const page=object(kid);
  assert.match(page,/\/Type\s*\/Page[^s]/);
  assert.match(page,/\/MediaBox\[0 0 792 612\]/);
  const streamObject=Number(/\/Contents (\d+) 0 R/.exec(page)[1]),stream=object(streamObject);
  const declared=Number(/\/Length (\d+)/.exec(stream)[1]),body=/stream\n([\s\S]*)endstream$/.exec(stream)[1];
  assert.equal(Buffer.byteLength(body,'latin1'),declared,'declared stream /Length matches its bytes');
  content+=body;
 }
 return {pageCount:kids.length,content,text:[...content.matchAll(/\((.*?)\) Tj/gs)].map(m=>m[1].replace(/\\([()\\])/g,'$1')).join('\n')};
}
export function readRtf(buffer){
 const text=buffer.toString('utf8');
 assert.match(text,/^\{\\rtf1\\ansi/,'RTF signature');
 let depth=0;for(let i=0;i<text.length;i++){if(text[i]==='\\'){i++;continue;}if(text[i]==='{')depth++;if(text[i]==='}')depth--;assert.ok(depth>=0,'RTF braces never close below the document');}
 assert.equal(depth,0,'RTF braces balance');
 const cells=[...text.matchAll(/\\cell(?![a-zA-Z])/g)].length,rows=[...text.matchAll(/\\row(?![a-zA-Z])/g)].length;
 return {text,cells,rows,plain:text.replace(/\\u(-?\d+)\?/g,(m,code)=>String.fromCharCode(Number(code)<0?Number(code)+65536:Number(code)))};
}

